from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageDetail
from taf.ul.ettf.ta_matchers.matchers import Any, Contains, ExpectationsBuilder, Omit, Range
from taf.ul.ettf.ta_matchers.templates import cell_identification, ul_configuration
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.pdml_parser.parser import Enum
from taf.ul.ettf.resources.expectations.lte_freq_band import get_band_info


class SCellToAddMod(ExpectationsBuilder):
    def __init__(self):
        super(SCellToAddMod, self).__init__("SCellToAddMod-r10")

    def with_scell_index(self, scell_index=Any()):
        self.append_element(key="sCellIndex-r10", element=scell_index)
        return self

    def with_cell_identification(self, cell_identification=Any()):
        self.append_element(key="cellIdentification-r10", element=cell_identification)
        return self

    def with_antenna_info_dedicated_scell(self, layers=None):
        self.append_element(key="antennaInfoDedicatedSCell-v10i0", element=layersMimo[layers])
        return self

    def with_radio_resource_config_common_scell(self, ul_configuration=Any()):
        self.append_element(key="radioResourceConfigCommonSCell-r10", element=ul_configuration)
        return self

    def with_physical_resource_config_dedicated_scell(self):
        self.append_element(key="radioResourceConfigDedicatedSCell-r10", element=Any())
        return self

    def with_physical_resource_config_dedicated_scell_containing_csr_layers(self, csr_layers=Any(), tm_mode=Any()):
        self.append_element(key="radioResourceConfigDedicatedSCell-r10", element=Any({
            'physicalConfigDedicatedSCell-r10': Any({
                'ul-Configuration-r10': Any({
                    'cqi-ReportConfigSCell-r10': Any()
                }),
                'nonUL-Configuration-r10': Any({
                    'antennaInfo-r10': template_antenna_info(csr=codebook_subset_restriction[csr_layers], tm=tm_mode)
                })
            })
        }))
        return self

    def with_physical_resource_config_dedicated_scell_without_csr_layers(self):
        self.append_element(key="radioResourceConfigDedicatedSCell-r10", element=Any({
            'physicalConfigDedicatedSCell-r10': Any({
                'ul-Configuration-r10': Any({
                    'cqi-ReportConfigSCell-r10': Any()
                }),
                'nonUL-Configuration-r10': Omit()
            })
        }))
        return self


e_tm = {
    'tm1': 0,
    'tm2': 1,
    'tm3': 2,
    'tm4': 3,
    'tm5': 4,
    'tm6': 5,
    'tm7': 6,
    'tm8-v920': 7,
    'tm9-v1020': 8,
    'tm10-v1130': 9,
}


def maxLayersMimoR10(layers, value):
    return Any({'maxLayersMIMO-r10': Enum(layers, value)})


layersMimo = {
    None: Omit(),
    'present': Any(),
    'twoLayers': maxLayersMimoR10('twoLayers', 0),
    'fourLayers': maxLayersMimoR10('fourLayers', 1),
    'eightLayers': maxLayersMimoR10('eightLayers', 2),
}


ul_dedicated_config = Any({
    'physicalConfigDedicatedSCell-r10': Any({
        'ul-Configuration-r10': Any({
            'uplinkPowerControlDedicatedSCell-r10': Any(),
            'cqi-ReportConfigSCell-r10': Any()
        })
    })
})


tdd_ul_configuration = Any({
    'ul-Configuration-r10': Any({
        'ul-FreqInfo-r10': Any({
            'ul-CarrierFreq-r10': Omit(),
            'additionalSpectrumEmissionSCell-r10': Any(),
        })
    })
})


codebook_subset_restriction = {
    'two_layers': '00000000ffffffff',
    'four_layers': 'ffffffffffffffff',
    'four_layers_tm9': 'f000ffffffffffff',
    'two_layers_2x2': 'fc'
}


def template_antenna_info(csr=Any(), tm=Any()):
    return Any({
        'transmissionMode-r10': Enum(tm, e_tm[tm]),
        'codebookSubsetRestriction-r10': csr
    })


def template_cqi_pcell(cqi_aperiodic=Any(), cqi_periodic=Any()):
    return Any({'cqi-ReportAperiodic-r10': Any({'setup':
                                               Any({'cqi-ReportModeAperiodic-r10': cqi_aperiodic})
                                                }),
               'cqi-ReportPeriodic-r10': Any({'setup':
                                              Any({'cqi-FormatIndicatorPeriodic-r10': Any({cqi_periodic: Any()})})
                                              })
                })


class carrier_aggregation(ExpectationsManager):
    @typed(index=int)
    def with_scell_release(self, index):
        self.append_expectation(MessageDetail('sCellToReleaseList-r10',
                                              Any({'SCellIndex-r10': index}),
                                              Contains))

    @typed(index=int)
    def with_not_changed_scell(self, index):
        partial_expectation = SCellToAddMod().with_scell_index(scell_index=index).\
            with_cell_identification(Omit()).\
            with_radio_resource_config_common_scell(Omit()).\
            with_antenna_info_dedicated_scell(). \
            with_physical_resource_config_dedicated_scell()

        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(index=int, cell_id=int, band=int, csr_layers=str, tm_mode=str, max_mimo=str)
    def with_not_changed_scell_containing_csr_layers(self, index, csr_layers, tm_mode, max_mimo=None):
        partial_expectation = SCellToAddMod().with_scell_index(scell_index=index).\
            with_cell_identification(Omit()).\
            with_radio_resource_config_common_scell(Omit()).\
            with_antenna_info_dedicated_scell(max_mimo). \
            with_physical_resource_config_dedicated_scell_containing_csr_layers(csr_layers=csr_layers, tm_mode=tm_mode)

        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(index=int)
    def with_not_changed_scell_without_csr_layers(self, index, max_mimo=None):
        partial_expectation = SCellToAddMod().with_scell_index(scell_index=index).\
            with_cell_identification(Omit()).\
            with_radio_resource_config_common_scell(Omit()).\
            with_antenna_info_dedicated_scell(max_mimo). \
            with_physical_resource_config_dedicated_scell_without_csr_layers()

        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    def with_no_scell(self):
        self.append_expectation(MessageDetail('sCellToAddModList-r10', Omit()))

    @typed(index=int, cell_id=int, band=int, max_mimo=str)
    def with_dl_scell(self, index, cell_id, band, max_mimo=None):
        band_info = get_band_info(band)
        partial_expectation = SCellToAddMod(). \
            with_scell_index(scell_index=index). \
            with_cell_identification(cell_identification=cell_identification(cell_id=cell_id,
                                                                             dl_carrier_freq=Range(band_info.dl_low_earfcn,
                                                                                                   band_info.dl_high_earfcn))). \
            with_antenna_info_dedicated_scell(max_mimo). \
            with_radio_resource_config_common_scell(). \
            with_physical_resource_config_dedicated_scell()
        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(index=int, cell_id=int, band=int, csr_layers=str, tm_mode=str, max_mimo=str)
    def with_dl_scell_containing_csr_layers(self, index, cell_id, band, csr_layers=None, tm_mode=None, max_mimo=None):
        band_info = get_band_info(band)
        partial_expectation = SCellToAddMod(). \
            with_scell_index(scell_index=index). \
            with_cell_identification(cell_identification=cell_identification(cell_id=cell_id,
                                                                             dl_carrier_freq=Range(band_info.dl_low_earfcn,
                                                                                                   band_info.dl_high_earfcn))). \
            with_antenna_info_dedicated_scell(max_mimo). \
            with_radio_resource_config_common_scell(). \
            with_physical_resource_config_dedicated_scell_containing_csr_layers(csr_layers=csr_layers, tm_mode=tm_mode)
        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(index=int, cell_id=int, band=int, csr_layers=str, tm_mode=str, max_mimo=str)
    def with_dl_ul_scell_containing_csr_layers(self, index, cell_id, band, csr_layers=None, tm_mode=None, max_mimo=None):
        band_info = get_band_info(band)
        partial_expectation = SCellToAddMod().\
            with_scell_index(scell_index=index).\
            with_cell_identification(cell_identification=cell_identification(cell_id=cell_id,
                                                                             dl_carrier_freq=Range(band_info.dl_low_earfcn,
                                                                                                   band_info.dl_high_earfcn))).\
            with_antenna_info_dedicated_scell(max_mimo).\
            with_radio_resource_config_common_scell(ul_configuration=ul_configuration(Range(band_info.ul_low_earfcn,
                                                                                            band_info.ul_high_earfcn))).\
            with_physical_resource_config_dedicated_scell_containing_csr_layers(csr_layers=csr_layers, tm_mode=tm_mode)
        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(index=int, cell_id=int, band=int, max_mimo=str)
    def with_dl_ul_scell(self, index, cell_id, band, max_mimo=None):
        band_info = get_band_info(band)
        partial_expectation = SCellToAddMod().\
            with_scell_index(scell_index=index).\
            with_cell_identification(cell_identification=cell_identification(cell_id=cell_id,
                                                                             dl_carrier_freq=Range(band_info.dl_low_earfcn,
                                                                                                   band_info.dl_high_earfcn))).\
            with_antenna_info_dedicated_scell(max_mimo). \
            with_radio_resource_config_common_scell(ul_configuration=ul_configuration(Range(band_info.ul_low_earfcn,
                                                                                            band_info.ul_high_earfcn))).\
            with_physical_resource_config_dedicated_scell()
        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(index=int, cell_id=int, band=int, max_mimo=str)
    def with_dl_ul_tdd_scell(self, index, cell_id, band, max_mimo=None):
        band_info = get_band_info(band)
        partial_expectation = SCellToAddMod().\
            with_scell_index(scell_index=index).\
            with_cell_identification(cell_identification=cell_identification(cell_id=cell_id,
                                                                             dl_carrier_freq=Range(band_info.dl_low_earfcn,
                                                                                                   band_info.dl_high_earfcn))).\
            with_antenna_info_dedicated_scell(max_mimo). \
            with_radio_resource_config_common_scell(ul_configuration=tdd_ul_configuration)
        self.append_expectation(MessageDetail('sCellToAddModList-r10', partial_expectation(), Contains))

    @typed(csr_layers=str, tm_mode=str, max_mimo=str)
    def with_pcell_antenna_info(self, csr_layers, tm_mode, max_mimo=None):
        self.append_expectation(MessageDetail('rrcConnectionReconfiguration-r8.physicalConfigDedicated',
                                              Any({'antennaInfo-r10': Any({
                                                  'explicitValue-r10': template_antenna_info(csr=codebook_subset_restriction[csr_layers], tm=tm_mode)
                                              })
                                              })))
        if max_mimo:
            self.append_expectation(MessageDetail('antennaInfoDedicatedPCell-v10i0', layersMimo[max_mimo]))

    @typed(csr_layers=str, tm_mode=str, max_mimo=str, cqi_aperiodic=str, cqi_periodic=str)
    def with_pcell_antenna_info_and_cqi(self, csr_layers, tm_mode, cqi_aperiodic, cqi_periodic, max_mimo=None):
        self.append_expectation(MessageDetail('rrcConnectionReconfiguration-r8.physicalConfigDedicated',
                                              Any({'antennaInfo-r10': Any({
                                                  'explicitValue-r10': template_antenna_info(csr=codebook_subset_restriction[csr_layers],
                                                                                             tm=tm_mode)}),
                                                   'cqi-ReportConfig-r10': template_cqi_pcell(cqi_aperiodic, cqi_periodic)
                                                   })
                                              )
                                )
        if max_mimo:
            self.append_expectation(MessageDetail('antennaInfoDedicatedPCell-v10i0', layersMimo[max_mimo]))

    @typed(max_mimo=str)
    def with_pcell_max_mimo(self, max_mimo):
        self.append_expectation(MessageDetail('antennaInfoDedicatedPCell-v10i0', layersMimo[max_mimo]))

    def with_not_changed_pcell(self):
        self.append_expectation(MessageDetail('rrcConnectionReconfiguration-r8.physicalConfigDedicated',
                                              Any({'antennaInfo-r10': Omit()})))
